-- The credentials the MCP door accepts: bearer tokens the owner issues (ADR-0009).
--
-- Generated by `drizzle-kit generate` from `db/schema.ts`, then finished by hand with the
-- comments and the trigger that keeps a revocation final. The secret itself is never here:
-- only its SHA-256, so a dump of this table opens nothing.

CREATE TABLE "access_tokens" (
	"id" text PRIMARY KEY DEFAULT gen_prefixed_id('tok') NOT NULL,
	"name" text NOT NULL,
	"secret_hash" text NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"last_used_at" timestamp with time zone,
	"revoked_at" timestamp with time zone,
	CONSTRAINT "access_tokens_secret_hash_key" UNIQUE("secret_hash"),
	CONSTRAINT "access_tokens_id_is_prefixed" CHECK ("access_tokens"."id" ~ '^tok_[a-z0-9]+(_[a-z0-9]+)*$'),
	CONSTRAINT "access_tokens_name_is_not_blank" CHECK ("access_tokens"."name" = btrim("access_tokens"."name") and "access_tokens"."name" <> ''),
	CONSTRAINT "access_tokens_secret_hash_is_a_sha256" CHECK ("access_tokens"."secret_hash" ~ '^[0-9a-f]{64}$')
);
