comment on table access_tokens is
  'Bearer tokens the owner issued for /mcp, one per place they went (Claude, laptop, tunnel). Stored as a hash; revoked, never deleted. Meant to hold every credential the door accepts, OAuth''s included when it exists.';
--> statement-breakpoint
comment on column access_tokens.name is
  'Where the token went, as the owner named it. Unique among the tokens not revoked.';
--> statement-breakpoint
comment on column access_tokens.secret_hash is
  'The SHA-256 of the secret, in hex. The secret is shown once when issued and kept nowhere.';
--> statement-breakpoint
comment on column access_tokens.last_used_at is
  'When the door last let it in, to the minute: touched at most once a minute, so a busy conversation is not a write per call.';
--> statement-breakpoint
comment on column access_tokens.revoked_at is
  'When the owner revoked it; null while it is live. Final: a revoked token is never made live again.';
--> statement-breakpoint

-- **A revocation is final, and a secret is what it was issued as.** Un-revoking would hand back
-- a door to whoever kept the old secret; changing the hash would be issuing a token without
-- showing it. Both are refused here rather than trusted to the verbs.
create function access_tokens_are_issued_once() returns trigger
language plpgsql
as $$
begin
  if old.revoked_at is not null and new.revoked_at is distinct from old.revoked_at then
    raise exception 'a revoked token stays revoked'
      using errcode = 'restrict_violation',
            constraint = 'access_tokens_revoked_is_final';
  end if;
  if new.secret_hash <> old.secret_hash then
    raise exception 'a token keeps the secret it was issued with'
      using errcode = 'restrict_violation',
            constraint = 'access_tokens_secret_is_final';
  end if;
  return new;
end;
$$;
--> statement-breakpoint
comment on function access_tokens_are_issued_once() is
  'A revoked token is never made live again, and no token changes its secret.';
--> statement-breakpoint
create trigger access_tokens_are_issued_once
  before update on access_tokens
  for each row execute function access_tokens_are_issued_once();
